INSERT INTO `tbl_document_tracking` VALUES (4905, NULL, '<p style=\"text-align: justify;\">Pursuant to Republic Act 11032 otherwise known as the \'Ease of Doing Business and Efficient Government Service Delivery Act of 2018\", mandated all offices and agencies which provide government services regularly undertake cost compliance analysis, time and re-engineer the some if deemed necessary to reduce bureaucratic red tape and processing time.</p>', '2025-11-20 14:52:59', 'INC-2025-421', '1', 'Office of the Municipal Mayor', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4906, NULL, '<p style=\"text-align: justify;\">In pursuit of providing better and more accessible services to its members and their beneficiaries the Social Security System (SSS) Tandag Branch will conduct SSS on Wheels Program on November 18, 2025 (Tuesday), from 9:00am to 3:00pm at the Carrascal Kiosk. In line with this, we encourage everyone to attend the said event.</p>', '2025-11-20 14:53:20', 'INC-2025-422', '1', 'Office of the Municipal Mayor', NULL);
