INSERT INTO `tbl_document_tracking` VALUES (4919, NULL, '<p style=\"text-align: justify;\">TANGGAPAN NG SANGGUNIANG PANLALAWIGAN</p>\n<p style=\"text-align: justify;\">TSP RESOLUTION NO. 395-25 (Series of 2025)</p>\n<p style=\"text-align: justify;\">RETURNING ORDINANCE NO. 31 DATED JULY 28, 2025 OF THE MUNICIPALITY OF CARRASCAL, THIS PROVINCE ENTITLED \"AN ORDINANCE CREATING THE POSITION OF ONE (1) SECURITY AGENT II, SALARY GRADE 10, COTERMINOUS STATUS AND PRIMARILY CONFIDENTIAL IN NATURE, UNDER THE OFFICE OF THE MUNICIPAL MAYOR\", FOR RECTIFICATION</p>', '2025-11-21', 'INC-2025-406', '1', 'TANGGAPAN NG SANGGUNIANG PANLALAWIGAN', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4920, NULL, '<p style=\"text-align: justify;\">Respectfully request the Honorable Sangguniang Bayan to review and amend the existing Municipal Ordinance No. 05, S. 2014 entitled \"An Ordinance for the regulation of smoking in public places, including public conveyances, advertisements, and promotions and sponsorships of tobacco products, and providing penalties thereof in accordance with tobacco regulation act of 2003 and its implementing rule.\"</p>', '2025-11-20', 'INC-2025-405', '1', 'Office of the MHO', NULL);
