INSERT INTO `tbl_document_tracking` VALUES (4926, NULL, '<p>MUNICIPAL HEALTH OFFICE</p>\n<p>Requesting the amendment of the Municipality\'s Anti-HIV/AIDS Ordinance of 2013, aligning the same with the provisions of Republic Act No.11166, otherwise known as the Philippine HIV and AIDS Policy Act of 2018.&nbsp;</p>', '2025-10-27', 'INC-2025-392', '1', 'Office of the MHO', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4927, NULL, '<p>SUBMISSION OF ENVIRONMENTAL WORK PROGRAM (3111) RENEWAL OF EP-XIII-028)</p>', '2025-11-19 16:37:35', 'INC-2025-393', '1', 'Morrys Y. Ang President, MMDC', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4928, NULL, '<p style=\"text-align: justify;\">RESOLUTION NO. 372-25 (Series of 2025)<br />AFFIRMING ORDINANCE NO. 32 DATED SEPTEMBER 8, 2025 OF THE MUNICIPALITY OF CARRASCAL, THIS PROVINCE ENTITLED \"AN ORDINANCE PROHIBITING MINORS FROM DRIVING MOTOR VEHICLES WITHIN THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR, PROVIDING PENALTIES FOR VIOLATION THEREOF, AND APPROPRIATING FUNDS FOR ITS IMPLEMENTATION\", IT BEING WITHIN THE SCOPE OF THE PRESCRIBED POWERS OF THE SANGGUNIANG BAYAN CONCERNED TO ENACT SUCH ORDINANCE PURSUANT TO THE LOCAL GOVERNMENT CODE OF 1991.</p>', '2025-11-20 14:44:19', 'INC-2025-394', '1', 'Edgar G. Perez,II,J.D Secretary to the Sangguniang Panlalawigan', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4929, NULL, '<p style=\"text-align: justify;\">In reference to the communication letter I have received last October 28,2025 regarding the request to update the Municipal Gender and Development Code, your good office has requested my presence before the legislative body for this concern. I regret to inform your office that I could not personally appear on the 16th Regular Session this November 3, 2025 because of an invitation for all BAC Members to attend Training on Procurement Service Client Engagement on November 3-5, 2025 at Butuan City.</p>', '2025-11-20 14:46:10', 'INC-2025-395', '1', 'Kresta Mae I. Pa-as RSW,MPA-MSWDO', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4930, NULL, '<p style=\"text-align: justify;\">Local Government Units with reference in fully implementing the Revised Philippine Government Internal Audit Manual (PGIAM) promulgated by the Department of Budget Management (DBM), the agency together with the CaragaBudget Administrators\' Group (CBAG) will be conducting a Training on Procurement Service Client Learning Engagement (CLE) on November 3-5, 2025. Relative to this, you are hereby directed to travel to Butuan City to attend the said activity on the<br />above-stated date, at the Grand Palace Hotel, Butuan City.</p>', '2025-11-20 14:13:02', 'INC-2025-396', '1', 'Office of the Municipal Mayor', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4931, NULL, '<p>MEMORANDUM ORDER NO. 142 2025</p>\n<p>MR. SOFRONILLO CORREOS<br />MR. EMBERTO F. ESTRADA<br />MR. ERNESTO A. WINES<br />MR. CRISTITO SUGIAN<br />MR. SERLIN E. VILLARIN<br />MR. EDUARDO P. URQUIA<br />MR. ROGER C. GUIRPtL<br />MR. LITO INTANO<br />MR. ALLAN P. URMENITA<br />MR. PAPINIANO P. CORPUZ<br />MR. JULIETO E. OCURA<br />MR. CLARO C. COMA<br />MR. MARLON P. RUAYANA<br />Job Order Workers<br />This Municipality</p>', '2025-11-20 14:15:13', 'INC-2025-397', '1', 'Office of the Municipal Mayor', NULL);
INSERT INTO `tbl_document_tracking` VALUES (4932, NULL, '<p style=\"text-align: justify;\">SPRN-452-25. AFFIRMING ORDINANCE NO. 28 (IP WELFARE &amp; DEVELOPMENT CODE)</p>', '2025-11-20 15:48:00', 'INC-2025-432', '1', 'TSP', NULL);
