INSERT INTO `tbl_document_tracking` VALUES (5381, NULL, '<p style=\"text-align: justify;\">TSP RESOLUTION NO. 3016-25 (Series of 2025)<br />AFFIRMING RESOLUTION NO. 49 DATED FEBRUARY 24, 2025 OF THE MUNICIPALITY OF CARRASCAL, THIS PROVINCE ENTITLED \"APPROVAL OF THE SUPPLEMENTAL ANNUAL INVESTMENT PROGRAM (AlP) NO. 1 PLANNING YEAR 2025 IN THE AMOUNT OF ONE HUNDRED THIRTY SEVEN MILLION NINETY FOUR THOUSAND THREE HUNDRED SEVENTY ONE PESOS AND 90/100 (P137,094,371.90) WITH THE FOLLOWING SOURCE OF FUNDS: GENERAL FUND<br />PROPER SURPLUS 2024 - P99,832,244.96; PS SAVINGS (2025 UNFILLED POSITION JANUARY &amp; FEBRUARY) - P2,311,468.85; LOCAL ECONOMIC ENTERPRISE SURPLUS 2024 - P1,561,054.44; SHARE FROM THE UTILIZATION OF NATIONAL WEALTH 2024 - P18,389,603.66 AND NFT-ELCAC - P15,000,000.00 OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR\", IT BEING WITHIN THE SCOPE OF THE PRESCRIBED POWERS OF THE SANGGUNIANG BAYAN CONCERNED PURSUANT TO THE LOCAL GOVERNMENT CODE OF 1991 SUBJECT TO VERIFICATION DURING THE SUBMISSION OF THE APPROPRIATION ORDINANCE TO ENSURE PLAN-BUDGET LINKAGE WHEREIN THE LOCAL BUDGETS TRULY OPERATIONALIZE APPROVED LOCAL DEVELOPMENT PLANS (SECTION 305 R.A. 7160) AND ARE CONSISTENT WITH THE BUDGET OPERATIONS MANUAL(BOM) FOR LGUs 2023 EDITION</p>', '2025-04-23', 'INC-2025-172', '1', 'TANGGAPAN NG SANGGUNIANG PANLALAWIGAN', NULL);
