INSERT INTO `tbl_document_tracking` VALUES (5650, NULL, '<p>TSP RESOLUTION NO. 2437-24 (Series of 2024)</p>\n<p style=\"text-align: justify;\">AFFIRMING RESOLUTION NO. 172 DATED SEPTEMBER 2, 2024 OF THE MUNICIPALITY OF CARRASCAL, THIS PROVINCE ENTITLED \"APPROVAL OF THE SUPPLEMENTAL ANNUAL INVESTMENT PROGRAM (AlP) NO. 3 FISCAL YEAR 2024 IN THE AMOUNT OF ONE HUNDRED FIFTY SEVEN MILLION SIX HUNDRED THIRTY FIVE THOUSAND FIVE HUNDRED SIXTY SEVEN PESOS (P 157,635,567.00) WITH THE FOLLOWING SOURCE OF FUNDS: PS SAVINGS (UNFILLED POSITIONS SB OFFICE AND MHO) - P 435,567.00; COLLECTIONS FROM HOSPITAL FEES P1,300,000.00; BUSINESS TAX - P 45,000,000.00; 20% SHARE IN THE PROCEEDS OF FIRE CODE FEES - P 85,258.52 AND SHARE FROM THE DEVELOPMENT OF NATIONAL WEALTH - P110,900,000.00 A TOTAL SOURCES OF ONE HUNDRED FIFTY SEVEN MILLION SEVEN HUNDRED TWENTY THOUSAND EIGHT HUNDRED TWENTY FIVE PESOS AND FIFTY TWO CENTAVOS<br />(P157,720,825.52) OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR\", IT BEING WITHIN THE SCOPE OF THE PRESCRIBED POWERS OF THE SANGGUNIANG BAYAN CONCERNED PURSUANT TO THE LOCAL GOVERNMENT CODE OF 1991, SUBJECT TO VERIFICATION DURING THE SUBMISSION OF THE APPROPRIATION ORDINANCE TO ENSURE PLAN-BUDGET LINKAGE WHEREIN THE LOCAL BUDGETS TRULY OPERATIONALIZE APPROVED LOCAL DEVELOPMENT PLANS (SECTION 305 (i) R.A. 7160) AND ARE CONSISTENT WITH THE BUDGET OPERATIONS MANUAL (BOM) FOR LGUs 2023 EDITION</p>', '2024-11-11', 'INC-2024-350', '1', 'TANGGAPAN NG SANGGUNIANG PANLALAWIGAN', NULL);
INSERT INTO `tbl_document_tracking` VALUES (5651, NULL, '<p style=\"text-align: justify;\">TSP RESOLUTION NO. 2507-24 (Series of 2024)<br />AFFIRMING ORDINANCE NO. 27 DATED SEPTEMBER 23, 2024 OF THE MUNICIPALITY OF CARRASCAL, THIS PROVINCE ENTITLED \"AN ORDINANCE IMPLEMENTING FORCED EVACUATION AS A RESORT WHEN A DISASTER OR EMERGENCY HAS BEEN DECLARED IN THE MUNICIPALITY AND A DANGER OF LOSS OF LIVES BECOMES IMMINENT, PROVIDING PENALTIES THEREFOR AND FOR OTHER PURPOSES\", IT BEING WITHIN THE SCOPE OF THE PRESCRIBED POWERS OF THE SANGGUNIANG BAYAN CONCERNED TO ENACT SUCH ORDINANCE PURSUANT TO THE LOCAL GOVERNMENT CODE OF 1991</p>', '2024-11-11', 'INC-2024-349', '1', 'TANGGAPAN NG SANGGUNIANG PANLALAWIGAN', NULL);
