INSERT INTO `tbl_document_tracking` VALUES (5819, NULL, '<p style=\"text-align: justify;\">TSP: Inviting Mr. Chester A. Azarcon to attend the scheduled meeting of the Committee on Good<br />Government, Public Ethics and Accountability on March 24, 2026 at 1:00 oclock in the afternoon at the SP Session Hall, Legislative Building, Capitol Hills, Telaje, Tandag City to discuss matters relative to the following ordinances, to wit:<br />1. Ordinance No. 08 dated February 9, 2026 of the Municipality of Carrascal, this Province entitled An Ordinance Amending Section 4 (Qualifications) of Municipal Ordinance No. 54, Series of 2025, Entitled An Ordinance Creating the Position of Administrative Officer IV (Information Officer I), Salary Grade 15, Under the Municipal Information Office of the Municipality of Carrascal, Surigao del Sur, for Purposes of Rectifying the Educational Requirement; and<br />2. Ordinance No. 09 dated February 9, 2026 of the Municipality of Carrascal, this Province entitled An Ordinance Amending Section 4 (Qualifications) of Municipal Ordinance No. 58, Series of 2025, Entitled An Ordinance Creating the Position of One (1) Administrative Officer I (Records Officer I). Salary Grade 10, Under the Municipal Health Office of the Municipality of Carrascal, Surigao del Sur, for Purposes of Rectifying the Educational Requirement.</p>', '2026-03-23', 'INC-2026-154', '1', 'TANGGAPAN NG SANGGUNIANG PANLALAWIGAN', NULL);
