INSERT INTO `tbl_ordinance` VALUES (800, 'ORD-2015-002', '\"AN ORDINANCE AMENDING SECTION I & III OF ORDINANCE NO. 03, S. 2006\r\n\"AN ORDINANCE REQUIRING ALL PUBLIC UTILITY VEHICLES SUCH AS VANS, BUSES, JEEPNEYS, MULTI-CABS AND OTHER SIMILAR TRANSPORT FACILITIES TO PARK EXCLUSIVELY AT CARRASCAL BUS TERMINAL LOCATED AT THE BACK OF PUBLIC MARKET FOR FIVE (5) MINUTES INTO \"AN ORDINANCE\r\nREQUIRING ALL PUBLIC UTILITY VEHICLES SUCH AS VANS, BUSES, JEEPNEYS,MULTI-CABS AND OTHER SIMILAR TRANSPORT FACILITIES TO PARK EXCLUSIVELY AT THE NEW CARRASCAL INTEGRATED TRANSPORT\r\nTERMINAL LOCATED AT BARANGAY GAMUTON, CARRASCAL, SURIGAO DEL SUR FOR FIVE (5) MINUTES WAITING FOR PASSENGERS THEREOF AND SECTION 3 PROHIBITIONS \" IT SHALL BE UNLAWFUL TO ANY OPERATORS OF\r\nCONVEYANCES, DRIVERS OF ALL PUBLIC UTILITY VEHICLES SUCH AS BUSES, VANS, JEEPNEYS, MULTI-CABS AND OTHER SIMILAR TRANSPORT FACILITIES TO PROCEED TO DESTINATION BOUND NORTH AND SOUTH WITHOUT PARKING FOR FIVE (5) MINUTES AT CARRASCAL INTEGRATED TRANSPORT TERMINAL LOCATED AT THE BACK OF THE PUBLIC MARKET WAITING PASSENGERS THEREOF\"INTO IT SHALL BE UNLAWFUL TO ANY OPERATORS OF CONVEYANCES, DRIVERS OF ALL PUBLIC UTILITY VEHICLES SUCH AS BUSES VANS, JEEPNEYS, MULTI-CABS AND SIMILAR TRANSPORT FACILITIES TO PROCEED TO DESTINATION BOUND NORTH AND SOUTH WITHOUT PARKIFCR FIVE (5) MINUTES A.T CARRASCAL INTEGRATED TRANSPORT TERMINAL LOCATED AT BARANGAY GAMUTON, CARRASCAL, SURR3A0 DEL SUR WAITING FOR PASSENGERS THEREAT WITH PARKING FEE FOR BUSES - PHP20M0; FOR VANS/JEEPNEYS PHPIO.00.\"', '2015-03-09', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2015-002', 'Ordinance');
