INSERT INTO `tbl_ordinance` VALUES (953, 'ORD-1994-011', '\"AN ORDINANCE IMPOSING RENTAL FEE FOR USE OF THE FUSO FIGHTER TRUCK OWNED BY THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR.\"', '1994-09-26', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-1994-011', 'Ordinance');
