INSERT INTO `tbl_ordinance` VALUES (955, 'ORD-2026-028', '\"AN ORDINANCE GRANTING CASH INCENTIVES TO OUTSTANDING INDIVIDUALS, TEAMS, AND COACHES OR TRAINERS FROM THE MUNICIPALITY OF CARRASCAL WHO EXCEL IN SPORTS, SKILLS, AND ACADEMIC COMPETITIONS, AND APPROPRIATING FUNDS THEREFOR.\"', '2026-05-04', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-028', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (956, 'ORD-2026-029', '\"AN ORDINANCE AMENDING SECTION 4 (QUALIFICATION) OF ORDINANCE NO. 44, SERIES OF 2025 OF THIS MUNICIPALITY, TO CORRECT THE EDUCATIONAL REQUIREMENT FOR THE POSITION OF ADMINISTRATIVE OFFICER V IN ACCORDANCE WITH CIVIL SERVICE COMMISSION STANDARDS.\"', '2026-06-08', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-029', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (957, 'ORD-2026-030', '\"AN ORDINANCE CREATING THE POSITION OF ENGINEER II (AGRICULTURAL AND BIOSYSTEMS), SALARY GRADE 16, UNDER THE MUNICIPAL AGRICULTURAL AND BIOSYSTEMS ENGINEER\'S OFFICE (MABEO) OF THE MUNICIPALITY OF CARRASCAL, AND PROVIDING FOR ITS FUNCTIONS AND COMPENSATION.\"', '2026-06-15', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-030', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (958, 'ORD-2026-031', 'SUPPLEMENTAL BUDGET NO. 2 FY 2026', '', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-031', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (959, 'ORD-2026-032', '\"AN ORDINANCE TRANSFERRING CERTAIN PLANTILLA POSITIONS FROM THE OFFICE OF THE SANGGUNIANG BAYAN TO THE OFFICE OF THE MUNICIPAL VICE MAYOR, AMENDING FOR THIS PURPOSE THE APPROVED STAFFING PATTERN OF THE MUNICIPAL GOVERNMENT OF CARRASCAL, AND FOR OTHER PURPOSES.\"', '2026-07-06', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-032', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (960, 'ORD-1992-015', '\"AN ORDINANCE ESTABLISHING THE FLOW OF TRAFFICE AND PRESVCRIBING REGULATION FOR LOADING AND UNLOADING OF PASSENGERS AND CARGOES EXCLUSIVELY AT THE BUS TERMINAL.\"', '1992-07-13', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-1992-015', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (963, 'ORD-2026-033', '\"AN ORDINANCE AMENDING ORDINANCE NO. 11, SERIES OF 2020, ENTITLED \"AN ORDINANCE CREATING THE INTERNAL AUDIT SERVICE OFFICE IN THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR,\" BY PROVIDING FOR THE ORGANIZATIONAL STRUCTURE, STAFFING PATTERN, AND DUTIES AND FUNCTIONS OF THE INTERNAL AUDIT SERVICE OFFICE, AND FOR OTHER PURPOSES.\"', '2026-07-20', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-033', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (964, 'ORD-2026-034', '\"AN ORDIANANCE AMENDING ORDINANCE NO. 12, SERIES OF 2020, BY CHANGING/RENAMING THE POSITION TITLE OF MUNICIPAL GOVERNMENT DEPARTMENT HEAD (INTERNAL AUDITOR), SALARY GRADE 24, INTO MUNICIPAL GOVERNMENT DEPARTMENT HEAD I (MUNICIPAL INTERNAL AUDIT SYSTEM OFFICER), SALARY GRADE 24, UNDER INTERNAL AUDIT SERVICE OFFICE OF THE MUNICIPAL OF CARRASCAL.\"', '2026-07-20', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-034', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (965, 'ORD-1992-019', '\"AN ORDIANANCE IMPOSING A MUNICIPAL TAX ON MINERAL AND FOREST PRODUCTS OF CARRASCAL, SURIGAO DEL SUR THAT SHALL GO OUT OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR.', '1992-12-07', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-1992-019', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (966, 'ORD-2026-035', '\"AN ORDINANCE INSTITUTIONALIZING THE SANGGUNIANG KABATAAN MONITORING \r\nAND EVALUATION SYSTEM IN THE MUNICIPALITY OF CARRASCAL, PROVINCE OF SURIGAO DEL SUR.\" ', '2026-08-03', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-035', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (967, 'ORD-2026-036', '\"AN ORDINANCE REGULATING THE ENTRY OF MIGRANTS WITHIN THE ANCESTRAL DOMAIN OF THE MUNICIPALITY OF CARRASCAL, AND HEREBY PROHIBITNG ITS SALE, TRANSFER OR DONATIONS TO NON-INDIGENOUS PEOPLE AND OTHER MIGRANTS, \r\nPURSUANT TO REPUBLIC ACT NO. 8371 (THE INDIGENOUS PEOPLE\'S ACT OF 1997), AND PROVIDING GUIDELINES FOR ITS IMPLEMENTATIONS.\" ', '2026-08-03', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-036', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (968, 'ORD-2026-037', '\"AN ORDINANCE AMENDING ORDINANCE NO, 38, SERIES OF 2025, ENTITLED \'AN ORDINANCE CREATING THE MUNICIPAL GENERAL SERVICES OFFICE IN THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR, AND PROVIDING FOR ITS FUNCTIONS,\' BY REVISING SECTION 4  THEREOF AND INSERTING NEW SECTIONS 4-A AND 4-13 TO PROVIDE FOR THE DUTIES AND FUNCTIONS OF ITS PERSONNEL, ORGANIZATIONAL STRUCTURE AND STAFFING PATTERN AND QUALIFICATION STANDARDS, AND FOR OTHER PURPOSES.\"', '2026-08-03', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-037', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (969, 'ORD-2026-038', '\"AN ORDINANCE AMENDING ORDINANCE NO. 30, SERIES OF 2026, BY CHANGING/RENAMING THE POSITION TITLE OF ENGINEER II (AGRICULTURAL AND BIOSYSTEMS) INTO ENGINEER II (AGRICULTURAL AND BIOSYSTEMS ENGINEER), SALARY GRADE 16, UNDER THE MUNICIPAL AGRICULTURAL AND BIOSYSTEMS ENGINEER\'S OFFICE OF THE MUNICIPALITY OF CARRASCAL.\"', '2026-08-24', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-038', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (970, 'ORD-2026-039', '\"AN ORDINANCE CREATING THE POSITION OF DISABILITY AFFAIRS OFFICER Ill, SALARY GRADE 18, UNDER THE MUNICIPAL PERSONS WITH DISABILITY AFFAIRS OFFICE (MPDAO) OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR, PRESCRIBING ITS\r\nQUALIFICATION STANDARDS, DEFINING ITS DUTIES AND FUNCTIONS, AND APPROPRIATING FUNDS THEREFOR.\"', '2026-09-14', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-039', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (971, 'ORD-2026-040', '\"AN ORDINANCE CREATING THE POSITION OF DISABILITY AFFAIRS OFFICER II, SALARY GRADE 15, UNDER THE MUNICIPAL PERSONS WITH DISABILITY AFFAIRS OFFICE (MPDAO) OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR, PRESCRIBINC ITS\r\nQUALIFICATION STANDARDS, DEFINING ITS DUTIES AND FUNCTIONS, AND APPROPRIATING FUNDS THEREFOR.\"', '2026-09-14', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-040', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (972, 'ORD-2026-041', '\"AN ORDINANCE CREATINC THE POSITION OF DISABILITY AFFAIRS ASSISTANT, SALARY GRADE 8, UNDER THE MUNICIPAL PERSONS WITH DISABILITY AFFAIRS OFFICE (MPDAO) OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DEL SUR, PRESCRIBING ITS\r\nQUALIFICATION STANDARDS, DEFINING ITS DUTIES AND FUNCTIONS, AND APPROPRIATING FUNDS THEREFOR.\"', '2026-09-14', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-041', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (973, 'ORD-2026-042', '\"AN ORDINANCE CREATING THE POSITION OF MUNICIPAL GOVERNMENT DEPARTMENT HEAD I (MUNICIPAL PESO MANAGER), SALARY GRADE 24, UNDER THE MUNICIPAL PUBLIC EMPLOYMENT SERVICE OFFICE (MPESO) OF THE MUNICIPALITY OF CARRASCAL, SURIGAO DELSUR, PRESCRIBING ITS QUALIFICATION STANDARDS, DEFINING ITS DUTIES\r\nAND FUNCTIONS, AND APPROPRIATING FUNDS THEREFOR.\"', '2026-09-14', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-042', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (974, 'ORD-2026-043', '\"AN ORDINANCE ORDINANCE NO. 43, SERIES OF 2026\r\nSTRENGTHENING THE SECURITY OF ALL PUBLIC AND PRIVATE EDUCATIONAL INSTITUTIONS WITHIN THE MUNICIPALITY TO ENSURE THE SAFETY OF STUDENTS, TEACHERS, AND SCHOOL PERSONNEL TO THE INCREASING INCIDENCE OF JUVENILE-RELATED CRIMES, PROVIDING GUIDELINES FOR THE SCHOOL SECURITY MEASURES, AND FOR THE OTHER PURPOSES.\"', '2026-09-14', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-043', 'Ordinance');
INSERT INTO `tbl_ordinance` VALUES (975, 'ORD-2026-044', 'ORDINANCE NO. 44,  SERIES OF 2026 \r\n\"AN ORDINANCE AMENDING APPROPRIATION ORDINANCE NO. 31, SERIES OF 2026, \r\nOTHERWISE KNOWN AS SUPPLEMENTAL BUDGET NO. 2 FOR FISCAL YEAR 2026 OF THE MUNICIPALITY OF CARRASCAL, BY CORRECTING THE CLASSIFICATION OF FIFTEEN MILLION EIGHT HUNDRED TEN THOUSAND THREE HUNDRED FIFTY-SIX PESOS AND FIFTY-SIX CENTAVOS (P15,810,356.56) FROM \"REALIGNMENT\" TO \"SAVINGS\" IN THE STATEMENT OF FUNDING SOURCES, REPLACING THE TERM \"REALIGNMENT\" WITH \"REAPPROPRIATION OF SAVINGS\" IN THE APPROPRIATE PROVISIONS THEREOF, AND \r\nFOR OTHER RELATED PURPOSES.\" ', '2026-09-14', '', 111, '', '', '28', '', '', '', '6', NULL, NULL, '', NULL, 'ORD-2026-044', 'Ordinance');
